    async function submeterFatura() {
        const dados = extrairDadosFormulario();

        if (dados.cliente_id <= 0) {
            App.showToast('Selecione um cliente para emitir a fatura.', 'error');
            return;
        }

        const status = document.getElementById('emissao-status')?.value || 'emitida';

        const payload = {
            cliente_id: dados.cliente_id,
            mes_referencia: dados.mes_referencia,
            consumo_kwh: dados.consumo_kwh,
            creditos_injetados_kwh: dados.consumo_kwh,
            iluminacao_publica: dados.iluminacao_publica,
            tarifa_kwh: dados.tarifa_kwh,
            valor_energisa: dados.subtotal,
            desconto_pct: dados.desconto_pct,
            valor_desconto: dados.valor_desconto,
            valor_cobrado: dados.total_cobrado,
            data_vencimento: dados.data_vencimento,
            status: status
        };

        if (anexoSelecionado) {
            payload.anexo_base64 = anexoSelecionado.base64;
            payload.anexo_nome = anexoSelecionado.nome;
        } else if (removerAnexoExistente) {
            payload.remover_anexo = true;
        }

        try {
            if (editingFaturaId) {
                await API.updateStartupFatura(editingFaturaId, payload);
                App.showToast(`Fatura #${editingFaturaId} atualizada com sucesso!`, 'success');
                editingFaturaId = null;
                anexoSelecionado = null;
                removerAnexoExistente = false;
                faturaEmEdicaoComAnexo = null;
            } else {
                await API.createStartupFatura(payload);
                App.showToast('Fatura padrão INJETAMT gerada e salva com sucesso!', 'success');
                anexoSelecionado = null;
                removerAnexoExistente = false;
                faturaEmEdicaoComAnexo = null;
            }
            switchTab('painel');
            load();
        } catch (err) {
            App.showToast(err.message, 'error');
        }
    }

    /**
     * Entra no modo de edição para uma fatura existente
     */
    async function editarFatura(faturaId) {
        try {
            let fat = faturasList.find(f => f.id == faturaId);
            if (!fat) {
                const resp = await API.getStartupFatura(faturaId);
                fat = resp?.fatura;
            }
            if (!fat) {
                App.showToast('Fatura não localizada.', 'error');
                return;
            }

            editingFaturaId = fat.id;
            anexoSelecionado = null;
            removerAnexoExistente = false;
            faturaEmEdicaoComAnexo = fat.arquivo_anexo ? { path: fat.arquivo_anexo, nome: fat.nome_arquivo_anexo || 'Fatura Energisa' } : null;
            switchTab('emissao');

            setTimeout(() => {
                const selectCli = document.getElementById('emissao-cliente');
                if (selectCli) selectCli.value = fat.cliente_id;

                const inputMes = document.getElementById('emissao-mes');
                if (inputMes) inputMes.value = fat.mes_referencia || '';

                const inputVenc = document.getElementById('emissao-vencimento');
                if (inputVenc) inputVenc.value = fat.data_vencimento || '';

                const inputConsumo = document.getElementById('emissao-consumo');
                if (inputConsumo) inputConsumo.value = parseFloat(fat.consumo_kwh || 0);

                const inputTarifa = document.getElementById('emissao-tarifa');
                if (inputTarifa) inputTarifa.value = parseFloat(fat.tarifa_kwh || 1.19);

                const inputTotalConsumo = document.getElementById('emissao-total-consumo');
                if (inputTotalConsumo) {
                    inputTotalConsumo.value = (parseFloat(fat.consumo_kwh || 0) * parseFloat(fat.tarifa_kwh || 1.19)).toFixed(2);
                }

                const inputIlum = document.getElementById('emissao-iluminacao');
                if (inputIlum) inputIlum.value = parseFloat(fat.iluminacao_publica || 0);

                const inputDesc = document.getElementById('emissao-desconto-pct');
                if (inputDesc) inputDesc.value = parseFloat(fat.desconto_pct || 20);

                const sliderDesc = document.getElementById('emissao-desconto-slider');
                if (sliderDesc) sliderDesc.value = parseFloat(fat.desconto_pct || 20);

                const lblDesc = document.getElementById('label-desconto-pct');
                if (lblDesc) lblDesc.innerText = `${parseFloat(fat.desconto_pct || 20)}%`;

                const selectStatus = document.getElementById('emissao-status');
                if (selectStatus) selectStatus.value = fat.status || 'emitida';

                atualizarUiModoEdicao();
                atualizarUiAnexo();
                recalcularPreview();

                App.showToast(`Modo de edição ativado para a Fatura #${fat.id}`, 'info');
            }, 60);
        } catch (err) {
            App.showToast(err.message, 'error');
        }
    }

    function cancelarEdicao() {
        editingFaturaId = null;
        anexoSelecionado = null;
        removerAnexoExistente = false;
        faturaEmEdicaoComAnexo = null;
        atualizarUiModoEdicao();
        atualizarUiAnexo();
        switchTab('painel');
    }

    
    function processarArquivoSelecionado(file) {
        if (!file) return;

        if (file.size > 20 * 1024 * 1024) {
            App.showToast('O arquivo deve ter no máximo 20 MB.', 'error');
            return;
        }

        const reader = new FileReader();
        reader.onload = () => {
            anexoSelecionado = {
                base64: reader.result,
                nome: file.name,
                size: file.size
            };
            removerAnexoExistente = false;
            atualizarUiAnexo();
            App.showToast(`Arquivo "${file.name}" pronto para ser salvo com a fatura!`, 'success');
        };
        reader.readAsDataURL(file);
    }

    function selecionarArquivoAnexo() {
        const inp = document.getElementById('emissao-arquivo-anexo');
        if (inp) {
            inp.value = '';
            inp.click();
        }
    }

    function removerArquivoSelecionado() {
        anexoSelecionado = null;
        removerAnexoExistente = true;
        faturaEmEdicaoComAnexo = null;
        const inp = document.getElementById('emissao-arquivo-anexo');
        if (inp) inp.value = '';
        atualizarUiAnexo();
        App.showToast('Anexo removido.', 'info');
    }

    function atualizarUiAnexo() {
        const btnTrigger = document.getElementById('btn-trigger-anexo');
        const txt = document.getElementById('btn-anexo-texto');
        const btnRemove = document.getElementById('btn-remover-anexo');

        if (anexoSelecionado) {
            if (txt) txt.innerText = `📄 ${anexoSelecionado.nome}`;
            if (btnTrigger) {
                btnTrigger.className = 'flex-1 px-3 py-2 bg-emerald-500/15 hover:bg-emerald-500/25 border border-emerald-500/30 rounded-xl text-xs font-bold text-emerald-300 transition-all flex items-center justify-center gap-1.5 truncate';
            }
            if (btnRemove) btnRemove.classList.remove('hidden');
        } else if (faturaEmEdicaoComAnexo && !removerAnexoExistente) {
            if (txt) txt.innerText = `📄 ${faturaEmEdicaoComAnexo.nome} (Trocar)`;
            if (btnTrigger) {
                btnTrigger.className = 'flex-1 px-3 py-2 bg-cyan-500/15 hover:bg-cyan-500/25 border border-cyan-500/30 rounded-xl text-xs font-bold text-cyan-300 transition-all flex items-center justify-center gap-1.5 truncate';
            }
            if (btnRemove) btnRemove.classList.remove('hidden');
        } else {
            if (txt) txt.innerText = '📎 Anexar Fatura';
            if (btnTrigger) {
                btnTrigger.className = 'flex-1 px-3 py-2 bg-zinc-900 hover:bg-zinc-800 border border-white/10 rounded-xl text-xs font-semibold text-zinc-300 hover:text-white transition-all flex items-center justify-center gap-1.5 truncate';
            }
            if (btnRemove) btnRemove.classList.add('hidden');
        }
    }

    function abrirVisualizadorAnexo(arquivoUrl, nomeArquivo = 'Fatura Original') {
        if (!arquivoUrl) {
            App.showToast('Nenhum arquivo anexado a esta fatura.', 'info');
            return;
        }

        const existing = document.getElementById('modal-visualizador-anexo');
        if (existing) existing.remove();

        const isPdf = arquivoUrl.toLowerCase().endsWith('.pdf') || arquivoUrl.includes('.pdf');

        const modalHtml = `
            <div id="modal-visualizador-anexo" class="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-5 bg-black/85 backdrop-blur-md">
                <div class="max-w-4xl w-full h-[88vh] bg-[#121217] border border-white/10 rounded-3xl p-4 sm:p-6 shadow-2xl flex flex-col space-y-3">
                    
                    <!-- Barra Superior -->
                    <div class="flex items-center justify-between pb-3 border-b border-white/10 flex-wrap gap-2 shrink-0">
                        <div class="flex items-center gap-2">
                            <span class="text-base text-cyan-400">📄</span>
                            <div>
                                <h4 class="text-sm font-extrabold text-white truncate max-w-md">${escapeHtml(nomeArquivo)}</h4>
                                <span class="text-[10px] text-zinc-400">Fatura Original Energisa Arquivada</span>
                            </div>
                        </div>
                        <div class="flex items-center gap-2">
                            <a href="${arquivoUrl}" target="_blank" download class="px-3.5 py-1.5 bg-zinc-800 hover:bg-zinc-700 text-zinc-200 font-bold text-xs rounded-full border border-white/10 transition-all flex items-center gap-1.5">
                                <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"></path></svg>
                                <span>Abrir / Baixar</span>
                            </a>
                            <button type="button" onclick="document.getElementById('modal-visualizador-anexo').remove()" class="text-zinc-400 hover:text-white p-2 rounded-xl hover:bg-white/5 transition-all text-base">
                                ✕
                            </button>
                        </div>
                    </div>

                    <!-- Conteúdo do Arquivo -->
                    <div class="flex-1 w-full h-full rounded-2xl overflow-hidden bg-zinc-950/50 border border-white/5 relative">
                        ${isPdf ? `
                            <iframe src="${arquivoUrl}" class="w-full h-full border-0 rounded-2xl bg-white"></iframe>
                        ` : `
                            <div class="w-full h-full flex items-center justify-center p-2 overflow-auto">
                                <img src="${arquivoUrl}" alt="Fatura" class="max-w-full max-h-full object-contain rounded-xl shadow-lg">
                            </div>
                        `}
                    </div>

                </div>
            </div>
        `;

        document.body.insertAdjacentHTML('beforeend', modalHtml);
    }

    function anexarFaturaDireta(faturaId) {
        const tempInput = document.createElement('input');
        tempInput.type = 'file';
        tempInput.accept = '.pdf,image/*';
        tempInput.onchange = async () => {
            const file = tempInput.files?.[0];
            if (!file) return;

            if (file.size > 20 * 1024 * 1024) {
                App.showToast('O arquivo deve ter no máximo 20 MB.', 'error');
                return;
            }

            App.showToast('Enviando anexo da fatura...', 'info');

            const reader = new FileReader();
            reader.onload = async () => {
                try {
                    await API.anexarStartupFatura(faturaId, {
                        anexo_base64: reader.result,
                        anexo_nome: file.name
                    });
                    App.showToast(`Fatura original "${file.name}" anexada com sucesso!`, 'success');
                    load();
                } catch (err) {
                    App.showToast(err.message, 'error');
                }
            };
            reader.readAsDataURL(file);
        };
        tempInput.click();
    }

    function atualizarUiModoEdicao() {
        const banner = document.getElementById('banner-modo-edicao');
        const submitText = document.getElementById('btn-submit-emissao-text');
        const btnCancelar = document.getElementById('btn-cancelar-edicao');
        const idDisplay = document.getElementById('edit-fatura-id-display');

        if (editingFaturaId) {
            if (banner) banner.classList.remove('hidden');
            if (idDisplay) idDisplay.innerText = editingFaturaId;
            if (submitText) submitText.innerText = '💾 Salvar Alterações';
            if (btnCancelar) btnCancelar.classList.remove('hidden');
        } else {
            if (banner) banner.classList.add('hidden');
            if (submitText) submitText.innerText = '⚡ Emitir & Salvar';
            if (btnCancelar) btnCancelar.classList.add('hidden');
        }
    }

