                mes_nome: obterNomeMes(fat.mes_referencia),
                data_vencimento: fat.data_vencimento,
                consumo_kwh: parseFloat(fat.consumo_kwh || 0),
                tarifa_kwh: parseFloat(fat.tarifa_kwh || 1.19),
